#include <stdio.h>
int main(void) {
    double ic = 4e8;
    double f1 = 2e9, cpi1 = 1.2;
    double f2 = 3e9, cpi2 = 2.0;
    double t1 = ic * cpi1 / f1;
    double t2 = ic * cpi2 / f2;
    printf("指令数 = 400000000\n");
    printf("旧 CPU: 主频 2.0GHz, CPI=1.2 -> 时间 = %.4f s\n", t1);
    printf("新 CPU: 主频 3.0GHz, CPI=2.0 -> 时间 = %.4f s\n", t2);
    printf("结论: 主频提升 50%%, 但 CPI 从 1.2 升到 2.0, 新机器%s\n", t2 > t1 ? "反而更慢" : "更快");
    printf("时间比 (旧/新) = %.4f\n", t1 / t2);
    return 0;
}
